# Securing Mathematical Expression Handling in Python

"Secure mathematical operations" almost always reduces to two separate problems, and conflating them is where most vulnerabilities come from:

1. **Untrusted input reaching an evaluator** → code injection (`eval`/`exec`, attribute access, imports).
2. **Untrusted input reaching an expensive operation** → algorithmic DoS (`9**9**9`, `"9"*10**7`, deep nesting).

You cannot fix #2 with a whitelist alone, and you cannot fix #1 with a timeout alone. Below is a layered design, followed by an OWASP mapping.

---

## Layer 0 — The non-negotiable rules

```python
# NEVER do any of these on untrusted input
eval(user_input)
exec(user_input)
eval(user_input, {"__builtins__": {}})   # still escapable via __subclasses__
compile(user_input, "<s>", "eval")
pickle.loads(user_input)
yaml.load(user_input)                    # use safe_load
float-formatted f-strings built from untrusted strings
```

The `{"__builtins__": {}}` trick is **not** a sandbox — object-graph traversal (`().__class__.__bases__[0].__subclasses__()`) recovers arbitrary callables. Never rely on it.

`ast.literal_eval` is *not* a math evaluator either: it accepts `1+2` only incidentally (complex-number support), has no operation limits, and rejects most real math.

---

## Layer 1 — Parse once, validate the AST, evaluate the same AST

The key structural rule: **never re-parse between validation and evaluation** (parse → validate → evaluate the *same tree*). And never use regex/string blacklists as the control — they are trivially bypassed.

```python
# safe_math.py
import ast
import math
import operator

class SafeExpressionError(ValueError):
    """Raised for any expression that is not provably safe."""

MAX_LEN        = 1_000     # characters
MAX_NODES      = 200       # AST node budget
MAX_DEPTH      = 20        # nesting depth
MAX_INT_BITS   = 4_096     # max bit-length of any intermediate int
MAX_EXPONENT   = 1_000     # max |exponent|

_BIN_OPS = {
    ast.Add: operator.add,   ast.Sub: operator.sub,
    ast.Mult: operator.mul,  ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,   ast.Pow: operator.pow,
}

_UNARY_OPS = {ast.UAdd: operator.pos, ast.USub: operator.neg}

_FUNCS = {
    "abs": abs, "min": min, "max": max, "round": round,
    "sqrt": math.sqrt, "log": math.log, "log10": math.log10,
    "exp": math.exp, "sin": math.sin, "cos": math.cos,
    "tan": math.tan, "floor": math.floor, "ceil": math.ceil,
}
_MAX_ARITY = {"min": 2, "max": 2}   # tighten per function


def safe_eval(expr: str) -> int | float:
    if not isinstance(expr, str):
        raise SafeExpressionError("expression must be a string")
    if len(expr) > MAX_LEN:
        raise SafeExpressionError("expression too long")

    try:
        tree = ast.parse(expr, mode="eval")   # parse ONCE
    except (SyntaxError, ValueError, MemoryError) as e:
        raise SafeExpressionError("invalid syntax") from e

    _validate(tree.body, depth=0, state=[0])   # validate the tree
    result = _eval(tree.body)                  # evaluate the SAME tree
    return _guard(result)


def _guard(v):
    if isinstance(v, int) and not isinstance(v, bool):
        if v.bit_length() > MAX_INT_BITS:
            raise SafeExpressionError("integer result too large")
    elif isinstance(v, float):
        if not math.isfinite(v):
            raise SafeExpressionError("non-finite result")
    else:
        raise SafeExpressionError(f"unsupported result type {type(v).__name__}")
    return v


def _validate(node, depth, state):
    state[0] += 1
    if state[0] > MAX_NODES:
        raise SafeExpressionError("expression too complex")
    if depth > MAX_DEPTH:
        raise SafeExpressionError("expression nested too deeply")

    if isinstance(node, ast.Constant):
        v = node.value
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise SafeExpressionError("only int/float literals are allowed")
        if isinstance(v, int) and v.bit_length() > MAX_INT_BITS:
            raise SafeExpressionError("literal too large")

    elif isinstance(node, ast.BinOp):
        if type(node.op) not in _BIN_OPS:
            raise SafeExpressionError(f"operator {type(node.op).__name__} disallowed")
        _validate(node.left, depth + 1, state)
        _validate(node.right, depth + 1, state)

    elif isinstance(node, ast.UnaryOp):
        if type(node.op) not in _UNARY_OPS:
            raise SafeExpressionError(f"unary {type(node.op).__name__} disallowed")
        _validate(node.operand, depth + 1, state)

    elif isinstance(node, ast.Call):
        if not isinstance(node.func, ast.Name) or node.func.id not in _FUNCS:
            raise SafeExpressionError("function call not allowed")
        if node.keywords:
            raise SafeExpressionError("keyword arguments not allowed")
        if len(node.args) < _MAX_ARITY.get(node.func.id, 1):
            raise SafeExpressionError("wrong number of arguments")
        for a in node.args:
            _validate(a, depth + 1, state)

    else:
        # Attribute, Subscript, Lambda, Comprehension, JoinedStr, NamedExpr,
        # Starred, Dict, List, Set, Await, ... — everything else is rejected.
        raise SafeExpressionError(f"node {type(node).__name__} not allowed")


def _eval(node):
    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.UnaryOp):
        return _guard(_UNARY_OPS[type(node.op)](_eval(node.operand)))

    if isinstance(node, ast.BinOp):
        left, right = _eval(node.left), _eval(node.right)

        if isinstance(node.op, ast.Pow):
            # Block 2**10**9 style blowups before computing.
            if isinstance(right, int) and abs(right) > MAX_EXPONENT:
                raise SafeExpressionError("exponent too large")
            if (isinstance(left, int) and abs(left) > 1
                    and isinstance(right, int) and right > MAX_EXPONENT):
                raise SafeExpressionError("exponent too large")

        if isinstance(node.op, (ast.Div, ast.FloorDiv, ast.Mod)) and right == 0:
            raise SafeExpressionError("division by zero")

        try:
            return _guard(_BIN_OPS[type(node.op)](left, right))
        except (ZeroDivisionError, OverflowError) as e:
            raise SafeExpressionError(str(e)) from e

    if isinstance(node, ast.Call):
        args = [_eval(a) for a in node.args]
        try:
            return _guard(_FUNCS[node.func.id](*args))
        except (ValueError, OverflowError, ZeroDivisionError) as e:
            raise SafeExpressionError(str(e)) from e

    raise SafeExpressionError("unreachable")
```

This single file covers: injection (no arbitrary names/attributes/calls), DoS by size, DoS by depth, DoS by big-int expansion, and NaN/Inf propagation
